const api=window.buildParty;
const $=selector=>document.querySelector(selector);
const copy={bold:'Orbit turns scattered launch work into one decisive path from idea to impact.',warm:'Orbit brings your people and launch work together, so every idea gets a clear path forward.',precise:'Plan, review, and approve every launch milestone in one shared workspace.'};
function render(state){
  const headline=state.headline||'Your next big idea, already in motion.';
  const tone=state.tone||'bold';
  const audience=state.audience||'creative teams';
  $('#message-preview-title').textContent=headline;
  $('#count').textContent=headline.length+' / 72';
  $('#tone-label').textContent=tone[0].toUpperCase()+tone.slice(1);
  $('#audience-kicker').textContent='For '+audience;
  $('#support').textContent=copy[tone]||copy.bold;
  document.querySelectorAll('[data-tone]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.tone===tone)));
  const channels=state.channels||{};
  const selected=[['email','Email'],['social','Social'],['inProduct','In-product']].filter(([key])=>channels[key]);
  $('#channel-row').innerHTML=selected.length?selected.map(([,label])=>'<span>'+label+'</span>').join(''):'<span>No channels selected</span>';
}
document.querySelectorAll('[data-tone]').forEach(button=>button.addEventListener('click',()=>api.patchState({tone:button.dataset.tone})));
$('#quick').addEventListener('click',()=>api.setState('headline','Turn launch chaos into momentum.'));
api.subscribe(render);
render(api.getState());

const api=window.buildParty;
const variants={momentum:{headline:'Move ideas<br>into <em>orbit.</em>',body:'One calm place to shape the story, align the team, and ship with confidence.',note:'Variant A · Momentum is active.'},clarity:{headline:'One launch.<br><em>Zero drift.</em>',body:'Plan every milestone, resolve every review, and know exactly when you are ready to ship.',note:'Variant B · Clarity is active.'}};
function render(state){
  const variant=state.variant||'momentum',view=state.view||'desktop',content=variants[variant];
  document.querySelector('#preview-headline').innerHTML=content.headline;
  document.querySelector('#preview-body').textContent=content.body;
  document.querySelector('#live-note').textContent=content.note;
  document.querySelector('#click-count').textContent=String(state.ctaClicks||0).padStart(2,'0');
  document.querySelector('#viewport').className='viewport '+view;
  document.querySelectorAll('[data-variant]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.variant===variant)));
  document.querySelectorAll('[data-view]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.view===view)));
}
document.querySelectorAll('[data-variant]').forEach(button=>button.addEventListener('click',()=>api.patchState({variant:button.dataset.variant})));
document.querySelectorAll('[data-view]').forEach(button=>button.addEventListener('click',()=>api.setState('view',button.dataset.view)));
document.querySelector('#cta').addEventListener('click',()=>api.setState('ctaClicks',(api.getState().ctaClicks||0)+1));
api.subscribe(render);
render(api.getState());

const api=window.buildParty;
const keys=['message','qa','analytics','support','legal','rollback'];
function render(state){
  const checks=state.checks||{},done=keys.filter(key=>checks[key]).length,percent=Math.round(done/keys.length*100),approval=state.approval||'pending';
  document.querySelector('#percent').textContent=percent+'%';
  document.querySelector('.dial').style.setProperty('--p',(percent*3.6)+'deg');
  document.querySelector('#meter-label').textContent=done===6?'Launch ready':done>=3?'In progress':'Getting started';
  document.querySelector('#check-count').textContent=done+' of '+keys.length;
  document.querySelector('#progress-fill').style.width=percent+'%';
  document.querySelector('.progress').setAttribute('aria-valuenow',String(done));
  const approve=document.querySelector('#approve'); approve.disabled=done!==keys.length;
  const box=document.querySelector('#decision-state'),label=box.querySelector('strong'),icon=box.querySelector(':scope > span');
  box.className='decision-state '+approval;
  if(approval==='approved'){label.textContent='Approved to launch';icon.textContent='✓'}else if(approval==='hold'){label.textContent='Changes requested';icon.textContent='!'}else{label.textContent=done===6?'Ready for decision':'Awaiting approval';icon.textContent='○'}
  const owner=state.approver||'Decision owner';
  document.querySelector('#record').textContent=approval==='approved'?'Approved by '+owner+'.':approval==='hold'?'Review held by '+owner+'.':'No decision recorded yet.';
}
document.querySelector('#approve').addEventListener('click',()=>api.patchState({approval:'approved'}));
document.querySelector('#hold').addEventListener('click',()=>api.setState('approval','hold'));
document.querySelector('#reset').addEventListener('click',()=>api.patchState({checks:Object.fromEntries(keys.map(key=>[key,false])),approval:'pending'}));
api.subscribe(render);
render(api.getState());
